package com.ruoyi.warehouse.orders;

import com.ruoyi.warehouse.carriers.*;
import com.ruoyi.warehouse.data.WarehouseRepository;
import com.ruoyi.warehouse.integrations.IntegrationJobLock;
import com.ruoyi.warehouse.support.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.warehouse.orders.OrderServiceTest.map;

class CarrierWorkflowTest {
    OrderServiceTest f;CarrierService service;CarrierTransport transport;Map<String,Object> config;String connection,order;AtomicInteger creates=new AtomicInteger(),labels=new AtomicInteger();String mode="normal";Runnable onCreate=()->{};
    @BeforeEach void setup(){
        f=new OrderServiceTest();f.database();when(f.scope.actor()).thenReturn(1L);
        f.jdbc.execute("CREATE TABLE wh_carrier_closed_request(actor_id BIGINT,request_id VARCHAR(64),request_kind VARCHAR(8),resource_id VARCHAR(64),PRIMARY KEY(actor_id,request_id,request_kind))");
        f.jdbc.execute("CREATE TABLE sys_user(user_id BIGINT PRIMARY KEY,status VARCHAR(1),del_flag VARCHAR(1))");f.jdbc.update("INSERT INTO sys_user VALUES(1,'0','0')");
        f.jdbc.execute("CREATE TABLE wh_carrier_connection(id VARCHAR(64) PRIMARY KEY,name VARCHAR(191),client_id VARCHAR(64),warehouse_id VARCHAR(64),config_json VARCHAR(1000000),credentials_cipher VARCHAR(10000),account_key CHAR(64),enabled BOOLEAN,revision BIGINT DEFAULT 1,last_request_id VARCHAR(64),last_input_hash CHAR(64),updated_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
        f.jdbc.execute("CREATE TABLE wh_carrier_shipment(id CHAR(64) PRIMARY KEY,connection_id VARCHAR(64),order_id VARCHAR(64),client_id VARCHAR(64),warehouse_id VARCHAR(64),actor_id BIGINT,request_id VARCHAR(64),request_hash CHAR(64),reference VARCHAR(25) UNIQUE,state VARCHAR(16),connection_revision BIGINT,snapshot_json VARCHAR(1000000),config_json VARCHAR(1000000),identity_json VARCHAR(1000000) DEFAULT '{}',error_code VARCHAR(64) DEFAULT '',revision BIGINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(actor_id,request_id))");
        f.jdbc.execute("CREATE TABLE wh_carrier_label(shipment_id CHAR(64),parcel_index INT,package_id VARCHAR(64),tracking_number VARCHAR(128),label_text VARCHAR(2100000),sha256 CHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(shipment_id,parcel_index))");
        var records=new WarehouseRepository(f.jdbc,f.scope);var access=new CarrierAccess(records,f.scope);f.service.setCarrierGuard(new CarrierOrderGuard(records,access));var locks=mock(IntegrationJobLock.class);when(locks.acquire(anyString())).thenAnswer(i->mock(IntegrationJobLock.Lease.class));
        transport=spy(new CarrierTransport(true,"",new MockEnvironment()));CarrierTransport.Client http=(path,method,headers,body)->{
            if(path.endsWith("/auth/access")){String token="c3ludGhldGlj."+Base64.getUrlEncoder().withoutPadding().encodeToString(WarehouseJson.write(Map.of("expiry",Instant.now().plusSeconds(3600).getEpochSecond(),"dpd_business_id",1)).getBytes(StandardCharsets.UTF_8))+".c2ln";return new CarrierTransport.Response(200,Map.of("data",Map.of("accessToken",token)),Map.of());}
            if(path.endsWith("/outboundservices"))return new CarrierTransport.Response(200,Map.of("data",List.of(Map.of("networkKey","SYNTHETIC-NETWORK","networkDesc","Synthetic domestic","notifyRequired","N"))),Map.of());
            if(path.endsWith("/domestic")){creates.incrementAndGet();onCreate.run();if(mode.equals("unknown"))return new CarrierTransport.Response(500,Map.of(),Map.of());if(mode.equals("reject"))return new CarrierTransport.Response(400,Map.of("error",List.of(Map.of("code",103))),Map.of());return new CarrierTransport.Response(200,Map.of("data",Map.of("shipmentId","synthetic-shipment","consignments",List.of(Map.of("consignmentNumber","synthetic-consignment","parcelNumber",List.of("15500000000001"),"parcelIds",List.of("synthetic-parcel"))))),Map.of());}
            if(path.contains("/labels?")){labels.incrementAndGet();if(mode.equals("label-error"))return new CarrierTransport.Response(500,Map.of(),Map.of());return new CarrierTransport.Response(200,Map.of("data",Map.of("printString",List.of("^XA^FO20,20^FDSYNTHETIC ONLY^FS^XZ"))),Map.of());}
            throw new AssertionError("Unexpected carrier path");
        };doReturn(http).when(transport).client(anyString(),any(Instant.class));byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);var vault=new CarrierVault(Base64.getEncoder().encodeToString(key));
        service=new CarrierService(access,vault,transport,locks,f.service,new DataSourceTransactionManager(f.jdbc.getDataSource()));
        var sender=map("name","Synthetic Sender","company","Warehouse","address1","1 Example Street","address2","","town","London","county","","postcode","SW1A1AA","country","GB","phone","02070000000","email","warehouse@example.test");config=map("environment","sandbox","businessUnit","DPD","printerDpi",203,"sender",sender);
        connection=(String)service.save(null,map("requestId",UUID.randomUUID().toString(),"name","Synthetic DPD","client","client","warehouse","warehouse","config",config,"credentials",map("appKey","synthetic-key","appSecret","synthetic-secret"),"enabled",true)).get("id");
        f.receive("product",5,"location","");var input=f.input(2);input.put("country","GB");input.put("postcode","SW1A 1AA");input.put("phone","02070000000");order=(String)f.save(null,input).get("id");var o=f.action(order,"allocate");var allocation=WarehouseJson.maps(o.get("allocations")).get(0);
        for(int i=0;i<2;i++){var body=map("requestId",UUID.randomUUID().toString(),"_version",o.get("_version"),"action","scan","allocationId",allocation.get("id"),"barcode","SYNTHETIC");o=f.tx.execute(s->f.service.workAction(order,body));}
        o=f.action(order,"pick");var pack=map("requestId",UUID.randomUUID().toString(),"_version",o.get("_version"),"action","pack","packageCode","SYNTHETIC-BOX","weightKg","1.25","lengthCm","30","widthCm","20","heightCm","10","lines",List.of(map("allocationId",allocation.get("id"),"quantity",2)));f.tx.execute(s->f.service.workAction(order,pack));
    }
    Map<String,Object> request(){return map("requestId",UUID.randomUUID().toString(),"connection",connection,"networkCode","SYNTHETIC-NETWORK","shipDate",LocalDate.now(ZoneId.of("Europe/London")).toString(),"notificationMobile","","_version",f.service.get(order).get("_version"),"connectionVersion",1);}
    @Test void closingAnUnseenRequestPreventsALateOriginalCreate(){var body=request();assertEquals(true,service.resolve("book",order,Map.of("requestId",body.get("requestId"))).get("requestClosed"));assertEquals("CARRIER_REQUEST_CLOSED",assertThrows(CarrierFailure.class,()->service.book(order,body)).code());assertEquals(0,creates.get());assertEquals("LABELLED",service.book(order,request()).get("state"));}
    @Test void resolvingKnownCreationReturnsOriginalWithoutNetworkRequests(){var body=request();var known=service.book(order,body);assertEquals(known,service.resolve("book",order,Map.of("requestId",body.get("requestId"))).get("shipment"));assertEquals(1,creates.get());}
    @Test void closingUnseenConfigurationRejectsTheLateSaveAndPreservesCurrentSettings(){String request=UUID.randomUUID().toString();var body=map("requestId",request,"_version",1,"name","Late changed name","client","client","warehouse","warehouse","config",config,"enabled",true);assertEquals(true,service.resolve("config",connection,Map.of("requestId",request)).get("requestClosed"));assertEquals("CARRIER_REQUEST_CLOSED",assertThrows(CarrierFailure.class,()->service.save(connection,body)).code());assertEquals("Synthetic DPD",service.connection(connection).get("name"));}
    @Test void originalLabelsPersistOnceAndFreezeWarehouseMutationWithoutConsumingStock(){var input=request();var result=service.book(order,input);assertEquals("LABELLED",result.get("state"));assertEquals(1,creates.get());assertEquals(1,labels.get());assertEquals(result,service.book(order,input));assertEquals(result,service.recover((String)result.get("id")));assertEquals(1,creates.get());assertEquals(1,labels.get());assertThrows(WarehouseException.class,()->f.action(order,"cancel"));assertThrows(WarehouseException.class,()->f.action(order,"despatch"));assertEquals(5,f.scalar("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(2,f.scalar("SELECT SUM(reserved) FROM wh_inventory"));assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_order_billing"));assertTrue(new String(service.label((String)result.get("id"),0),StandardCharsets.UTF_8).startsWith("^XA"));}
    @Test void labelFailureKeepsKnownShipmentAndRecoveryNeverRepeatsCreation(){mode="label-error";var result=service.book(order,request());assertEquals("CREATED",result.get("state"));assertFalse(((Map<?,?>)result.get("identity")).isEmpty());mode="normal";assertEquals("LABELLED",service.recover((String)result.get("id")).get("state"));assertEquals(1,creates.get());assertEquals(2,labels.get());}
    @Test void unknownRemoteCreationAndCrashSendingStateCannotResend(){mode="unknown";var input=request();var result=service.book(order,input);assertEquals("UNKNOWN",result.get("state"));assertEquals("UNKNOWN",service.book(order,input).get("state"));assertThrows(WarehouseException.class,()->service.book(order,request()));assertEquals(1,creates.get());f.jdbc.update("UPDATE wh_carrier_shipment SET state='SENDING' WHERE id=?",result.get("id"));assertEquals("UNKNOWN",service.recover((String)result.get("id")).get("state"));assertEquals(1,creates.get());}
    @Test void documentedFieldRejectionAllowsANewAttemptButNeverReplaysTheRejectedOne(){mode="reject";var original=request();var result=service.book(order,original);assertEquals("REJECTED",result.get("state"));mode="normal";assertEquals("REJECTED",service.book(order,original).get("state"));assertEquals(1,creates.get());assertEquals("LABELLED",service.book(order,request()).get("state"));assertEquals(2,creates.get());}
    @Test void sendIntentAuditFailureRollsBackBeforeAnyRemoteCreation(){f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT fail_carrier_intent CHECK(action_name<>'CARRIER_SEND_INTENT')");var result=service.book(order,request());assertEquals("REJECTED",result.get("state"));assertEquals(0,creates.get());assertEquals("CANCELLED",f.action(order,"cancel").get("status"));}
    @Test void knownReceiptIsRetainedAfterOperatorAccessIsRevokedDuringCreation(){onCreate=()->f.jdbc.update("UPDATE sys_user SET status='1' WHERE user_id=1");var failure=assertThrows(CarrierFailure.class,()->service.book(order,request()));assertEquals("CARRIER_ACCESS_REVOKED",failure.code());assertEquals("CREATED",f.jdbc.queryForObject("SELECT state FROM wh_carrier_shipment",String.class));assertTrue(f.jdbc.queryForObject("SELECT identity_json FROM wh_carrier_shipment",String.class).contains("synthetic-shipment"));assertEquals(1,creates.get());assertEquals(0,labels.get());}
    @Test void accountEnvironmentAndRoutingCannotBeReboundAfterUse(){var current=service.connection(connection);var body=map("requestId",UUID.randomUUID().toString(),"_version",current.get("_version"),"name",current.get("name"),"client","client","warehouse","warehouse","config",config,"credentials",map("appKey","another-key","appSecret","another-secret"),"enabled",true);assertThrows(WarehouseException.class,()->service.save(connection,body));assertEquals(1L,((Number)service.connection(connection).get("_version")).longValue());}
    @Test void stoppingRuntimePreventsAnyNetworkCallBeforeCreatingTheShipment(){doThrow(new CarrierFailure("CARRIER_RUNTIME_DISABLED")).when(transport).requireEnabled();assertThrows(CarrierFailure.class,()->service.book(order,request()));assertEquals(0,creates.get());assertEquals(0,f.scalar("SELECT COUNT(*) FROM wh_carrier_shipment"));}
}
